const icon = (name, size = 16) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.feed}</svg>`;
const levels = {ordinary:'普通',featured:'精选',rare:'稀有',exclusive:'独家'};
const evidenceNames = {peer_reviewed:'同行评审',preprint:'预印本',official:'官方进展',repository:'开源项目',unverified:'待核验'};
const statuses = {pending:'待审核',published:'已发布',rejected:'未通过',disputed:'已证伪',expired:'已失效'};
const fallbackCategories = ['前沿科技','人工智能','生命科学','物理','化学','地球与地理','天文与空间','材料科学','开源技术','军事与国防','政治与公共政策','农业与食品','社会民生','法律法规','航空航天','经济与产业','能源与环境','医疗健康','教育与就业','交通与基建','公共安全','生活实用','省钱优惠','招聘求职','职业成长','住房居住','出行旅行','商业创业'];
const fallbackTravelTopics = ['签证入境','景点避坑','交通住宿','优惠渠道','支付通信','季节天气','安全提醒'];
const fallbackTravelRegions = ['东亚','东南亚','南亚','中亚','西亚','欧洲','非洲','北美洲','南美洲','大洋洲','南极洲','跨地区'];
const unlockCosts = {ordinary:1,featured:2,rare:4,exclusive:8};
const state = {boot:null,user:null,view:'all',category:'',country:'',region:'',travelTopic:'',level:'',sort:'latest',q:'',page:1,items:[],total:0,routeID:0,adminTab:'queue',adminContentStatus:'all',adminContentPage:1,adminContentQuery:'',admin:null,billingOrder:null,authMode:'login',invite:new URLSearchParams(location.search).get('invite')||'',codeUntil:0};
let toastTimer, searchTimer, paymentPollTimer=null, paymentPollGeneration=0;

function safeURL(value) { try { const url = new URL(String(value)); return ['https:','http:'].includes(url.protocol) ? url.href : ''; } catch { return ''; } }
function dateText(value, long = false) { if (!value) return '时间待核对'; const date = new Date(value); if (Number.isNaN(date.getTime())) return '时间待核对'; return date.toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',...(long?{hour:'2-digit',minute:'2-digit'}:{})}).replaceAll('/','.'); }
function isHistoricalGap(g){return Boolean(g.released_at&&g.created_at&&new Date(g.released_at).getTime()<new Date(g.created_at).getTime());}
function releaseLabel(g){return isHistoricalGap(g)?'历史资料公开':'本站发布';}
function formatNumber(value) { return Number(value || 0).toLocaleString('zh-CN'); }
function delayHours(user=state.user){if(isStaff(user))return 0;return hasReading(user)?Math.max(0,Number(user.reading_delay_hours??user.entitlements?.delay_hours)||0):0;}
function delayText(hours){return Number(hours)===0?'实时可见':`延后 ${Number(hours)} 小时`;}
function dailyAllowance(user=state.user){return Math.max(0,Number(user?.daily_allowance??1));}
function unlockCost(g){const cost=Number(g.unlock_cost);return Number.isFinite(cost)&&cost>0?cost:unlockCosts[g.level]||1;}
function rankCredits(user=state.user){return Math.max(0,Number(user?.rank_credits)||0)+Math.max(0,Number(user?.invite_credits)||0);}
function rankCreditExpiry(user=state.user){const dates=[Number(user?.rank_credits)>0?user?.rank_credits_expires_at:'',Number(user?.invite_credits)>0?user?.invite_credits_expires_at:''].filter(d=>d&&!Number.isNaN(Date.parse(d))).sort((a,b)=>Date.parse(a)-Date.parse(b));return rankCredits(user)>0?(dates[0]?`最近 ${dateText(dates[0],true)} 到期`:'按批次有效期使用'):'暂无可用限时赠分';}
function availableCredits(user=state.user){const total=Number(user?.available_credits);return user?.available_credits!==undefined&&Number.isFinite(total)?Math.max(0,total):Math.max(0,Number(user?.daily_remaining)||0)+rankCredits(user)+Math.max(0,Number(user?.credits)||0);}
function unlockBudget(g){const cost=unlockCost(g),daily=Math.max(0,Number(state.user?.daily_remaining)||0),rank=rankCredits(),credits=Math.max(0,Number(state.user?.credits)||0),fromDaily=Math.min(cost,daily),fromRank=Math.min(Math.max(0,cost-fromDaily),rank);return {cost,daily,rank,credits,total:daily+rank+credits,fromDaily,fromRank,fromCredits:Math.max(0,cost-fromDaily-fromRank),enough:daily+rank+credits>=cost};}
function canReadGap(g){return Boolean(state.user&&(g.unlocked===true||['admin','reviewer'].includes(state.user.role)));}
function canViewSources(g){return canReadGap(g)&&(g.source_visibility!=='internal'||['admin','reviewer'].includes(state.user?.role));}
function sourceLabel(g){if(!canViewSources(g))return canReadGap(g)&&g.source_visibility==='internal'?'社区线索':'来源随详情解锁';return g.source_name||(!g.source_url?'社区线索':'来源待核对');}
function sourceVisibilityTag(g){return g.source_visibility==='internal'&&['admin','reviewer'].includes(state.user?.role)?'<span class="source-private">来源仅后台可见</span>':'';}
function evidenceTag(value) { return `<span class="evidence-tag evidence-${Object.hasOwn(evidenceNames,value)?value:'unverified'}">${esc(evidenceNames[value] || '待核验')}</span>`; }
function levelTag(value) { return `<span class="level-tag level-${Object.hasOwn(levels,value)?value:'ordinary'}">${esc(levels[value]||'普通')}</span>`; }
function isGapCode(value){const match=/^(PT|JX|XY|DJ)(?:-([A-Z]{2})-)?(\d{2,})$/i.exec(String(value||'').trim());return Boolean(match&&/[1-9]/.test(match[3])&&(!match[2]||!state.boot?.topic_codes||Object.values(state.boot.topic_codes).includes(match[2].toUpperCase())));}
function gapCode(g){const code=typeof g.code==='string'?g.code.trim():'';return isGapCode(code)?`<span class="gap-code" title="信息编号 ${esc(code)}" aria-label="信息编号 ${esc(code)}">${esc(code)}</span>`:'';}
function empty(title, description, action = '') { return `<div class="empty-state">${icon('book',30)}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`; }
function loading() { return '<div class="loading-state"><span class="spinner"></span><p>正在加载…</p></div>'; }
function toast(message) { clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200); }
async function api(path, options = {}) {
  let response;try{response=await fetch(path,{credentials:'same-origin',...options,headers:{'Accept':'application/json',...(!['GET','HEAD'].includes(String(options.method||'GET').toUpperCase())?{'Content-Type':'application/json'}:{}),...options.headers}});}catch(error){if(error instanceof TypeError)throw new Error('网络暂时未连接，请检查网络后重试；如已付款，请先核对订单，勿重复支付。');throw error;}
  const data = await response.json().catch(()=>({error:'服务暂时没有响应，请稍后重试'}));
  if (!response.ok) { const error=new Error((data.error || `请求失败（${response.status}）`)+(data.request_id?`（问题编号 ${data.request_id}）`:""));error.status=response.status;error.requestID=data.request_id||"";throw error; }
  return data;
}
const post=(path,body={})=>api(path,{method:'POST',body:JSON.stringify(body)});
async function busy(button, fn) { if(button?.disabled)return;const label=button?.innerHTML;if(button){button.disabled=true;button.classList.add('loading-btn');}try{return await fn();}catch(error){toast(error.message);if(error.status===401)openAuth();}finally{if(button&&button.isConnected){button.disabled=false;button.classList.remove('loading-btn');button.innerHTML=label;}} }

// A deliberately small Markdown renderer. Raw HTML and image syntax are never executed.
function inlineMarkdown(text) {
  const regex = /(`[^`\n]+`|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\(https?:\/\/[^\s)]+\)|https?:\/\/[^\s<>]+)/g;
  let out='',last=0,match;
  while((match=regex.exec(String(text)))){
    out+=esc(String(text).slice(last,match.index));const t=match[0];
    if(t.startsWith('`'))out+=`<code>${esc(t.slice(1,-1))}</code>`;
    else if(t.startsWith('**'))out+=`<strong>${esc(t.slice(2,-2))}</strong>`;
    else if(t.startsWith('[')){const m=t.match(/^\[([^\]]+)\]\((.+)\)$/);const url=safeURL(m[2]);out+=url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(m[1])}</a>`:esc(t);}
    else{const url=safeURL(t);out+=url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(t)}</a>`:esc(t);}
    last=match.index+t.length;
  }
  return out+esc(String(text).slice(last));
}
function markdown(text) {
  const lines=String(text||'').replaceAll('\r','').split('\n');let out='',paragraph=[],listType='',list=[],code=null;
  const flushParagraph=()=>{if(paragraph.length){out+=`<p>${paragraph.map(inlineMarkdown).join('<br>')}</p>`;paragraph=[];}};
  const flushList=()=>{if(list.length){out+=`<${listType}>${list.map(x=>`<li>${inlineMarkdown(x)}</li>`).join('')}</${listType}>`;list=[];listType='';}};
  for(let i=0;i<lines.length;i++){
    const line=lines[i];
    if(line.trim().startsWith('```')){flushParagraph();flushList();if(code===null){code=[];}else{out+=`<pre><code>${esc(code.join('\n'))}</code></pre>`;code=null;}continue;}
    if(code!==null){code.push(line);continue;}
    if(!line.trim()){flushParagraph();flushList();continue;}
    const head=line.match(/^(#{1,4})\s+(.+)$/);
    if(head){flushParagraph();flushList();const n=Math.min(4,head[1].length+1);out+=`<h${n}>${inlineMarkdown(head[2])}</h${n}>`;continue;}
    if(/^\s*([-*_])\1\1+\s*$/.test(line)){flushParagraph();flushList();out+='<hr>';continue;}
    if(/^>\s?/.test(line)){flushParagraph();flushList();out+=`<blockquote><p>${inlineMarkdown(line.replace(/^>\s?/,''))}</p></blockquote>`;continue;}
    const li=line.match(/^\s*(?:([-*])\s+|(\d+)\.\s+)(.+)$/);
    if(li){flushParagraph();const type=li[2]?'ol':'ul';if(listType&&listType!==type)flushList();listType=type;list.push(li[3]);continue;}
    if(line.includes('|')&&i+1<lines.length&&/^\s*\|?\s*:?-{3,}/.test(lines[i+1])){
      flushParagraph();flushList();const split=row=>row.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(x=>x.trim());const headers=split(line);i+=2;const rows=[];while(i<lines.length&&lines[i].includes('|')){rows.push(split(lines[i]));i++;}i--;
      out+=`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${inlineMarkdown(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${inlineMarkdown(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;continue;
    }
    flushList();paragraph.push(line);
  }
  flushParagraph();flushList();if(code!==null)out+=`<pre><code>${esc(code.join('\n'))}</code></pre>`;return out;
}
function highlight(text,tags){const words=(Array.isArray(tags)?tags:[]).filter(t=>typeof t==='string'&&t.length>=2).slice(0,10);if(!words.length)return esc(text);const pattern=new RegExp('('+words.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');return String(text||'').split(pattern).map((part,i)=>i%2?`<mark>${esc(part)}</mark>`:esc(part)).join('');}

function travelOptions(kind){const values=state.boot?.['travel_'+kind];return Array.isArray(values)&&values.length?values:kind==='regions'?fallbackTravelRegions:fallbackTravelTopics;}
function travelMeta(tags){const values={country:'',region:'',travel_topic:''};for(const tag of Array.isArray(tags)?tags:[]){const m=String(tag).match(/^(国家|地区|旅行):(.+)$/);if(m){const key={国家:'country',地区:'region',旅行:'travel_topic'}[m[1]];if(!values[key])values[key]=m[2];}}return values;}
function plainTags(tags){return (Array.isArray(tags)?tags:[]).filter(t=>!/^(国家|地区|旅行):/.test(t));}
function displayTags(tags){return (Array.isArray(tags)?tags:[]).map(t=>String(t).replace(/^(国家|地区|旅行):/,''));}
function travelBadges(g){if(g.category!=='出行旅行')return '';const items=(Array.isArray(g.tags)?g.tags:[]).map(t=>String(t).match(/^(国家|地区|旅行):(.+)$/)).filter(Boolean).slice(0,10);return items.length?`<div class="travel-badges" aria-label="旅行信息">${items.map(([,label,value])=>`<span title="${label==='旅行'?'旅行标签':label}">${esc(value)}</span>`).join('')}</div>`:'';}
function travelControls(prefix,values={},draft=false){const name=key=>draft?'travel_'+key:key;return `<div class="travel-fields-grid"><div class="field"><label for="${prefix}-country">国家或目的地</label><input id="${prefix}-country" name="${name('country')}" list="${prefix}-countries" maxlength="42" value="${esc(values.country||'')}" placeholder="${draft?'输入适用国家，跨国内容可留空':'输入国家，或留空查看全球'}" autocomplete="off"><datalist id="${prefix}-countries"></datalist></div><div class="field"><label for="${prefix}-region">地区</label><select id="${prefix}-region" name="${name('region')}"><option value="">${draft?'暂不标注':'全部地区'}</option>${travelOptions('regions').map(v=>`<option ${v===values.region?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="${prefix}-topic">旅行标签</label><select id="${prefix}-topic" name="${name('topic')}"><option value="">${draft?'暂不标注':'全部标签'}</option>${travelOptions('topics').map(v=>`<option ${v===values.travel_topic?'selected':''}>${esc(v)}</option>`).join('')}</select></div></div>`;}
function travelDraftFields(prefix,category,tags=[]){return `<section class="travel-draft-fields wide" id="${prefix}-travel-fields" ${category==='出行旅行'?'':'hidden'}><h3>旅行信息</h3>${travelControls(prefix,travelMeta(tags),true)}<p class="hint" id="${prefix}-travel-hint">标注适用国家、地区和旅行标签，方便成员查找。三项与其他标签合计最多 10 个；跨国内容可选“跨地区”。${Object.entries({country:'国家',region:'地区',travel_topic:'旅行'}).map(([key,label])=>{const values=(Array.isArray(tags)?tags:[]).filter(t=>String(t).startsWith(label+':')).map(t=>String(t).slice(3));return values.length>1?`<br>现有${label==='旅行'?'旅行标签':label}：${values.map(esc).join('、')}。修改该栏会替换这些标注。`:'';}).join('')}</p></section>`;}
function travelFilters(){return `<form id="travel-filter-form" class="travel-filters" aria-label="全球旅行筛选"><div class="travel-filter-heading"><strong>全球旅行</strong><span>签证、避坑与优惠渠道</span></div>${travelControls('travel-filter',{country:state.country,region:state.region,travel_topic:state.travelTopic})}<div class="travel-filter-footer"><p id="travel-filter-travel-hint">国家可直接输入；候选仅来自当前可见的已收录内容。</p><div><button class="btn small" type="button" data-reset-travel>清除旅行筛选</button><button class="btn primary small" type="submit">应用筛选</button></div></div><div id="travel-filter-error" class="form-error" role="alert"></div></form>`;}
async function loadTravelCountries(prefix,token){try{const data=await api('/api/travel/facets');if(token!==state.routeID)return;const target=$('#'+prefix+'-countries');if(target)target.innerHTML=(Array.isArray(data.countries)?data.countries:[]).filter(c=>typeof c==='string').map(c=>`<option value="${esc(c)}"></option>`).join('');}catch(error){if(token!==state.routeID)return;const hint=$('#'+prefix+'-travel-hint');if(hint)hint.textContent='国家候选暂时没有加载成功，可直接输入国家名称。';}}
function clearTravelFilters(){state.country='';state.region='';state.travelTopic='';}
function setSearchQuery(query){state.q=String(query||'').trim();state.page=1;if(isGapCode(state.q)){state.category='';state.level='';clearTravelFilters();}}
function validateTravelCountry(value){if([...value].length>21||/[\u0000-\u001f\u007f-\u009f<>]/.test(value))throw new Error('国家名称不能超过 21 个字，请去掉特殊符号。');}
function collectFormTags(data,originalTags=[]){
  const categories=state.boot?.categories?.length?state.boot.categories:fallbackCategories;if(typeof data.category!=='string'||!categories.includes(data.category))throw new Error('每条信息只选择一个有效主题。');
  const tags=String(data.tags||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean);
  if(tags.some(t=>/^(国家|地区|旅行):/.test(t)))throw new Error('旅行信息请填写在国家、地区和旅行标签栏，标签栏中不用重复。');
  if(data.category==='出行旅行'){
    const country=String(data.travel_country||'').trim(),region=String(data.travel_region||'').trim(),topic=String(data.travel_topic||'').trim();validateTravelCountry(country);
    if(region&&!travelOptions('regions').includes(region))throw new Error('请选择列表中的地区。');
    if(topic&&!travelOptions('topics').includes(topic))throw new Error('请选择列表中的旅行标签。');
    const original=travelMeta(originalTags);
    for(const [prefix,key,value] of [['国家','country',country],['地区','region',region],['旅行','travel_topic',topic]]){if(value&&value===original[key])tags.push(...originalTags.filter(t=>typeof t==='string'&&t.startsWith(prefix+':')));else if(value)tags.push(prefix+':'+value);}
  }
  const unique=[...new Set(tags)];if(unique.length>10)throw new Error('标签与旅行信息合计最多 10 个，请删减后再提交。');if(unique.some(t=>[...t].length>24))throw new Error('每个标签不能超过 24 个字。');
  delete data.travel_country;delete data.travel_region;delete data.travel_topic;return unique;
}

function categoryNavigation(categories,route){
  const publicAffairs=new Set(['军事与国防','政治与公共政策','法律法规','公共安全']);
  const dailyLife=new Set(['农业与食品','社会民生','经济与产业','能源与环境','医疗健康','教育与就业','交通与基建']);
  const opportunities=['省钱优惠','招聘求职','生活实用','职业成长','住房居住','出行旅行','商业创业'];
  const groups=[['开源工具',categories.filter(c=>c==='开源技术')],['生活与机会',opportunities.filter(c=>categories.includes(c))],['科学与技术',categories.filter(c=>c!=='开源技术'&&!publicAffairs.has(c)&&!dailyLife.has(c)&&!opportunities.includes(c))],['产业与民生',categories.filter(c=>dailyLife.has(c))],['公共事务',categories.filter(c=>publicAffairs.has(c))]];
  return groups.filter(([,items])=>items.length).map(([label,items])=>`<details class="category-group" ${items.includes(state.category)||(!state.category&&['开源工具','生活与机会'].includes(label))?'open':''}><summary><span>${label}</span><small>${formatNumber(items.reduce((n,c)=>n+Number(state.boot?.category_counts?.[c]||0),0))}</small></summary>${items.map(c=>`<button class="nav-link ${state.category===c&&route==='feed'?'active':''}" data-category="${esc(c)}"><span class="category-dot c${categories.indexOf(c)%8}"></span>${c==='开源技术'?'全部开源工具':esc(c)}<span class="count">${formatNumber(state.boot?.category_counts?.[c]||0)}</span></button>`).join('')}</details>`).join('');
}

function isStaff(user=state.user){return Boolean(user&&['admin','reviewer'].includes(user.role));}
function hasReading(user=state.user){return Boolean(user?.reading_active);}
function readingLabel(user=state.user){return isStaff(user)?'管理阅读':hasReading(user)?'畅读中':'积分阅读';}
function discountPercent(points=state.user?.points){const n=Number(points)||0;return n>=2500?80:n>=1400?85:n>=700?90:n>=300?92:n>=100?95:100;}
function discountText(percent){return Number(percent)>=100?'原价':`${Number((Number(percent)/10).toFixed(1))} 折`;}
function readingStatus(user=state.user){if(isStaff(user))return '全部内容实时可读，不扣积分';if(hasReading(user))return `${delayText(delayHours(user))} · 期限内不限次阅读${user.reading_until?' · 至 '+dateText(user.reading_until,true):''}`;return '信息实时展示，详情使用积分解锁';}
