async function loadCentOrders(){const target=$('#membership-orders');if(!target)return;if(state.user?.test_mode){target.textContent='返回管理员模式后可查看真实测试订单。';return;}try{const data=await api('/api/billing/orders');if(target.isConnected){const items=(data.items||[]).filter(o=>billingType(o)==='payment_test');target.innerHTML=billingOrderList(items);if(!state.billingOrder&&items[0])await renderCheckout(items[0]);}}catch(error){if(target.isConnected)target.innerHTML=`<p class="form-error">${esc(error.message)}</p><button class="btn small" data-retry-cent-orders>重新加载订单</button>`;}}
async function runDiagnostic(button,group){
 const target=$('#diagnostic-results');if(!target)return;
 $$('.diagnostic-controls button').forEach(b=>b.disabled=true);target.innerHTML=loading();const token=state.routeID;
 try{const result=await post('/api/admin/diagnostics',{group});if(token!==state.routeID)return;state.diagnosticResult=result;
 target.innerHTML=`<section class="panel"><div class="list-heading"><h2>${result.passed?'本次流程检查通过':'发现需要处理的项目'}</h2><button class="btn small" data-copy-diagnostic>复制检查结果</button></div><p class="tiny-note">${esc(result.id)} · 版本 ${esc(result.version)} · ${dateText(result.at,true)} · ${formatNumber(result.duration_ms)} 毫秒</p>${(result.checks||[]).map(c=>`<div class="diagnostic-check"><strong class="${c.status==='failed'||c.status==='unavailable'?'diagnostic-bad':'diagnostic-good'}">${esc({passed:'通过',failed:'未通过',ready:'配置就绪',unavailable:'未就绪'}[c.status]||c.status)}</strong><div><h3>${esc(c.name)}</h3><p>${esc(c.detail)}</p></div></div>`).join('')}<p class="tiny-note">${esc(result.notice)}</p></section>`;
 }catch(error){if(token===state.routeID)target.innerHTML=empty('本次检查未完成',error.message);}finally{if(token===state.routeID)$$('.diagnostic-controls button').forEach(b=>b.disabled=false);}
}
function openTestMode(){
 if(!state.user?.can_test_mode)return;closeMenu();const u=state.user,currentMonths=u.test_mode&&hasReading(u)?({8:1,4:3,2:6,0:12}[delayHours(u)]||0):0;
 $('#dialog-content').innerHTML=`<div class="dialog-inner"><button class="icon-btn dialog-close" data-close-dialog aria-label="关闭">${icon('close',17)}</button><div class="eyebrow">TEST / 用户体验</div><h2>切换测试用户模式</h2><p>用独立测试账号体验阅读、积分与订阅。这里展示的是模拟权益，不会改变正式账号。</p><form id="test-mode-form"><div class="field"><label for="test-reading">模拟阅读方式</label><select id="test-reading" name="reading_months">${[[0,'普通用户 · 实时信息，积分解锁'],[1,'1 个月会员 · 延后 8 小时畅读'],[3,'3 个月会员 · 延后 4 小时畅读'],[6,'6 个月会员 · 延后 2 小时畅读'],[12,'12 个月会员 · 实时畅读']].map(([v,n])=>`<option value="${v}" ${currentMonths===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="test-credits">模拟永久积分</label><input id="test-credits" name="credits" type="number" min="0" max="100000" value="${u.test_mode?Math.max(0,Number(u.credits)||0):100}" required></div><div class="field"><label for="test-points">模拟贡献值</label><input id="test-points" name="points" type="number" min="0" max="100000" value="${u.test_mode?Math.max(0,Number(u.points)||0):0}" required><span class="hint">用于验证贡献折扣，不改变正式排行榜。</span></div><label class="test-check"><input name="reset" type="checkbox" checked>清空测试阅读、收藏和订阅，重新体验</label><p class="tiny-note">正式付款、投稿和反馈仍以真实账号为准。</p><div id="test-mode-error" class="form-error" role="alert"></div><button class="btn primary full" type="submit">应用并进入用户视角</button></form></div>`;
 if(!$('#dialog').open)$('#dialog').showModal();$('#test-reading').focus();
}

async function afterTestModeChange(admin=false){
 state.admin=null;state.billingOrder=null;state.currentGap=null;state.q='';state.category='';state.level='';clearTravelFilters();state.page=1;state.view='all';
 await refreshBoot();$('#dialog').close();const target=admin?'admin':'feed';if(location.hash==='#'+target)await route();else location.hash=target;
}
function openReport(id){if(!state.user){openAuth();return;}$('#dialog-content').innerHTML=`<div class="dialog-inner"><button class="icon-btn dialog-close" data-close-dialog aria-label="关闭">${icon('close',17)}</button><div class="eyebrow">REVIEW / 帮助核对</div><h2>这条信息哪里需要修正？</h2><p>请说明具体问题。附上新的证据或来源，有助于审核员快速核对。</p><form id="report-form" data-id="${esc(id)}"><div class="field"><label for="report-reason">问题与依据</label><textarea id="report-reason" name="reason" required minlength="10" maxlength="2000" rows="5"></textarea></div><button type="submit" class="btn primary full">提交反馈</button></form></div>`;$('#dialog').showModal();}
function closeMenu(){$('#sidebar').classList.remove('open');$('#sidebar-scrim').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');}
function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('infogap-theme',theme);}catch{}$('#theme-toggle').innerHTML=icon(theme==='dark'?'sun':'moon',16);$('#theme-toggle').setAttribute('aria-label',theme==='dark'?'切换浅色主题':'切换深色主题');}
function routeTo(path){if(location.hash==='#'+path)route();else location.hash=path;}
async function route(){
  stopPaymentPolling();closeMenu();if($('#dialog').open)$('#dialog').close();const token=++state.routeID;const route=(location.hash.slice(1)||'feed').split('?')[0];renderShell();window.scrollTo({top:0});
  if(route==='courses')return renderCourses(token);if(route.startsWith('course-manage/'))return renderCourseManage(decodeURIComponent(route.slice(14)),token);if(route.startsWith('course/'))return renderCourse(decodeURIComponent(route.slice(7)),token);
  if(route.startsWith('gap/'))return renderArticle(decodeURIComponent(route.slice(4)),token);
  if(route.startsWith('edit/'))return renderEdit(decodeURIComponent(route.slice(5)),token);if(route.startsWith('my-edit/'))return renderMySubmissionEdit(decodeURIComponent(route.slice(8)),token);if(route==='mine')return renderMySubmissions(token);
  if(route==='feedback'||route.startsWith('feedback/'))return window.InfoGapFeedback.render({user:state.user,api,post,esc,dateText,toast,token,currentToken:()=>state.routeID,id:route.startsWith('feedback/')?route.slice(9):null});
  if(route==='subscriptions')return renderSubscriptions(token);if(route==='membership')return renderMembership(token);
  if(route==='diagnostics')return renderDiagnostics();if(route==='submit')return renderSubmission();if(route==='profile')return renderProfile(token);if(route==='leaderboard')return renderLeaderboard();if(route==='ranks'||route==='benefits')return renderRanks();if(route==='guide')return renderGuide();if(route==='rules')return renderRules();if(route==='admin'){await renderAdmin(token);if(token===state.routeID)showFirstGuide(route);return;}
  state.view=({feed:'all',saved:'saved',unlocked:'unlocked',mine:'mine',subscribed:'subscribed'})[route]||'all';await renderFeed(token);if(token===state.routeID)showFirstGuide(route);
}
async function refreshBoot(){const prior=String(state.user?.id||'')+':'+String(state.user?.role||'');state.boot=await api('/api/bootstrap');state.user=state.boot.user||null;if(prior!==String(state.user?.id||'')+':'+String(state.user?.role||'')){state.readerTrail=[];state.readerVisited=new Set();state.readerChoices=null;state.admin=null;}renderShell();}
