  const neighbor=event.target.closest('[data-read-neighbor]');if(neighbor){await openNeighbor(neighbor);return;}if(event.target.closest('[data-neighbor-retry]')){await loadArticleNeighbors(state.currentGap,state.routeID);return;}
  const recordPage=event.target.closest('[data-record-page]');if(recordPage&&['orders','behaviors'].includes(state.adminTab)){state['admin_'+state.adminTab].page=Math.max(1,Number(recordPage.dataset.recordPage)||1);await renderAdminRecords();return;}if(event.target.closest('[data-record-retry]')){await renderAdminRecords();return;}
  const save=event.target.closest('[data-save]');if(save){if(!state.user){openAuth();return;}await busy(save,async()=>{const data=await post('/api/gaps/'+encodeURIComponent(save.dataset.save)+'/save');toast(data.saved?'已加入收藏':'已取消收藏');const g=state.items.find(g=>String(g.id)===save.dataset.save);if(g)g.saved=data.saved;if(location.hash.startsWith('#gap/')){await route();}else if(state.view==='saved'){await route();}else{save.classList.toggle('saved',data.saved);save.setAttribute('aria-label',data.saved?'取消收藏':'收藏这条信息');}});return;}
  const unlock=event.target.closest('[data-unlock]');if(unlock){await busy(unlock,async()=>{try{const data=await post('/api/gaps/'+encodeURIComponent(unlock.dataset.unlock)+'/unlock');state.user=data.user;renderShell();toast('详情已解锁，重读不再扣减额度');await route();}catch(error){const target=$('#unlock-error');if(target){target.innerHTML=esc(error.message)+(error.status===402?' <a href="#submit">贡献获得额度</a> · <a href="#membership">购买长期额度</a>':'');}else{throw error;}if(error.status===401)openAuth();}});return;}
