  const myPage=event.target.closest('[data-my-page]');if(myPage){state.myPage=Math.max(1,Number(myPage.dataset.myPage)||1);await renderMySubmissions(state.routeID);return;}if(event.target.closest('[data-my-retry]')){await renderMySubmissions(state.routeID);return;}const reloadEdit=event.target.closest('[data-reload-my-edit]');if(reloadEdit){await busy(reloadEdit,()=>renderMySubmissionEdit(reloadEdit.dataset.reloadMyEdit,state.routeID,true));return;}const deduction=event.target.closest('[data-deduct-credits]');if(deduction){openCreditDeduction(deduction.dataset.deductCredits);return;}if(event.target.closest('[data-reload-revisions]')){await renderAdminRevisions();return;}const revisionReview=event.target.closest('[data-revision-review]');if(revisionReview){await reviewRevision(revisionReview);return;}
