  if(event.target.closest('[data-admin-content-retry]')){renderAdminContentList();return;}
  const adminTab=event.target.closest('[data-admin-tab]');if(adminTab){state.adminTab=adminTab.dataset.adminTab;renderAdminContent();return;}
