  const disabled=event.target.closest('[data-user-disabled]');if(disabled){await busy(disabled,async()=>{await post('/api/admin/users/'+encodeURIComponent(disabled.dataset.id),{disabled:disabled.dataset.userDisabled==='true'});toast('账号状态已更新');await reloadAdmin();});return;}
